package br.com.erp.pos;
import br.com.erp.auth.*;
import br.com.erp.inventory.StockService;
import br.com.erp.shared.Audit;
import java.math.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import static br.com.erp.pos.PosCommercialContracts.*;
@Service
public class DiscountService {
 private final JdbcTemplate db;private final BranchAccess access;private final CartPricing pricing;private final CashService cash;private final Audit audit;
 public DiscountService(JdbcTemplate db,BranchAccess access,CartPricing pricing,CashService cash,Audit audit){this.db=db;this.access=access;this.pricing=pricing;this.cash=cash;this.audit=audit;}
 private ResponseStatusException error(HttpStatus s,String text){return new ResponseStatusException(s,text);}
 private void lock(Actor a){db.queryForObject("SELECT id FROM tenant WHERE id=? FOR UPDATE",UUID.class,a.tenantId());}
 private String note(String text){String n=text.trim();if(n.length()<5)throw error(HttpStatus.BAD_REQUEST,"Justificativa deve conter cinco caracteres.");return n;}
 @Transactional(readOnly=true) public Policy policy(Actor a,UUID branch){access.requireBranch(a,branch);var rows=db.query("SELECT operator_percent,version FROM pos_discount_policy WHERE tenant_id=? AND branch_id=?",(r,i)->new Policy(branch,r.getBigDecimal(1),r.getLong(2)),a.tenantId(),branch);return rows.isEmpty()?new Policy(branch,BigDecimal.ZERO,0):rows.getFirst();}
 @Transactional public Policy policy(Actor a,UUID branch,PolicyInput input){lock(a);pricing.require(a,"pos:discount-policy");var old=policy(a,branch);if(old.version()!=input.version())throw error(HttpStatus.CONFLICT,"Política alterada. Atualize.");if(old.version()==0)db.update("INSERT INTO pos_discount_policy(tenant_id,branch_id,operator_percent,version,updated_by,updated_at) VALUES(?,?,?,1,?,?)",a.tenantId(),branch,input.operatorPercent(),a.userId(),OffsetDateTime.now(ZoneOffset.UTC));else db.update("UPDATE pos_discount_policy SET operator_percent=?,version=version+1,updated_by=?,updated_at=? WHERE tenant_id=? AND branch_id=?",input.operatorPercent(),a.userId(),OffsetDateTime.now(ZoneOffset.UTC),a.tenantId(),branch);audit.record(a,"POS_DISCOUNT_POLICY",branch);return policy(a,branch);}
 @Transactional(readOnly=true) public Approval get(Actor a,UUID id){var rows=db.query("SELECT d.*,u.name AS requested_by_name FROM pos_discount_request d JOIN app_user u ON u.tenant_id=d.tenant_id AND u.id=d.requested_by WHERE d.tenant_id=? AND d.id=?",(r,i)->new Approval(r.getObject("id",UUID.class),r.getObject("branch_id",UUID.class),r.getObject("requested_by",UUID.class),r.getString("status"),r.getLong("version"),r.getLong("policy_version"),r.getString("note"),r.getBigDecimal("gross_total"),r.getBigDecimal("discount_total"),pricing.decode(r.getString("items_json")),r.getObject("created_at",OffsetDateTime.class),r.getObject("decided_by",UUID.class),r.getString("decision_note"),r.getObject("expires_at",OffsetDateTime.class),r.getObject("sale_id",UUID.class),r.getString("requested_by_name")),a.tenantId(),id);if(rows.isEmpty())throw error(HttpStatus.NOT_FOUND,"Solicitação não encontrada.");var request=rows.getFirst();access.requireBranch(a,request.branchId());if(!request.requestedBy().equals(a.userId())&&!pricing.has(a,"pos:discount-approve"))throw error(HttpStatus.NOT_FOUND,"Solicitação não encontrada.");return request;}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Map<String,Object> list(Actor a,String status,int page,int size){boolean manager=pricing.has(a,"pos:discount-approve");String where=" WHERE d.tenant_id=? AND "+BranchAccess.predicate("d.branch_id")+" AND (?=TRUE OR d.requested_by=?) AND (?='' OR d.status=?)";var ids=db.query("SELECT d.id FROM pos_discount_request d"+where+" ORDER BY d.created_at DESC,d.id LIMIT ? OFFSET ?",(r,i)->r.getObject(1,UUID.class),a.tenantId(),a.tenantId(),a.userId(),manager,a.userId(),status,status,size,(long)page*size);return Map.of("items",ids.stream().map(id->get(a,id)).toList(),"total",db.queryForObject("SELECT COUNT(*) FROM pos_discount_request d"+where,Long.class,a.tenantId(),a.tenantId(),a.userId(),manager,a.userId(),status,status),"page",page,"size",size);}
 @Transactional public Approval request(Actor a,CartInput input){lock(a);pricing.require(a,"pos:discount");var session=cash.get(a,input.sessionId());pricing.owner(a,session);String note=note(input.note());var fields=new ArrayList<Object>(List.of("DISCOUNT_REQUEST",session.branchId(),a.userId(),note));for(var i:input.items())Collections.addAll(fields,i.productId(),i.quantity(),i.expectedUnitPrice(),CartPricing.discount(i));String hash=StockService.fingerprint(fields.toArray());var old=db.query("SELECT id,fingerprint FROM pos_discount_request WHERE tenant_id=? AND request_id=?",(r,i)->Map.entry(r.getObject(1,UUID.class),r.getString(2)),a.tenantId(),input.requestId());if(!old.isEmpty()){if(!hash.equals(old.getFirst().getValue()))throw error(HttpStatus.CONFLICT,"Identificador reutilizado.");return get(a,old.getFirst().getKey());}if(!session.status().equals("OPEN"))throw error(HttpStatus.CONFLICT,"Solicitação exige caixa aberto.");var quote=pricing.quote(a,session.branchId(),input.items());if(quote.discountTotal().signum()<=0)throw error(HttpStatus.BAD_REQUEST,"Carrinho não possui desconto.");UUID id=UUID.randomUUID();db.update("INSERT INTO pos_discount_request(id,tenant_id,request_id,fingerprint,branch_id,requested_by,cart_hash,items_json,gross_total,discount_total,note,created_at,policy_version) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",id,a.tenantId(),input.requestId(),hash,session.branchId(),a.userId(),quote.hash(),pricing.encode(quote.items()),quote.grossTotal(),quote.discountTotal(),note,OffsetDateTime.now(ZoneOffset.UTC),policy(a,session.branchId()).version());audit.record(a,"POS_DISCOUNT_REQUESTED",id);return get(a,id);}
 @Transactional public Approval decide(Actor a,UUID id,DecisionInput input){lock(a);pricing.require(a,"pos:discount-approve");var request=get(a,id);String note=note(input.note()),hash=StockService.fingerprint("DISCOUNT_DECISION",id,input.version(),input.approve(),note,a.userId());var old=db.query("SELECT id,decision_fingerprint FROM pos_discount_request WHERE tenant_id=? AND decision_request_id=?",(r,i)->Map.entry(r.getObject(1,UUID.class),r.getString(2)),a.tenantId(),input.requestId());if(!old.isEmpty()){if(!old.getFirst().getKey().equals(id)||!old.getFirst().getValue().equals(hash))throw error(HttpStatus.CONFLICT,"Identificador de decisão reutilizado.");return request;}if(request.requestedBy().equals(a.userId()))throw error(HttpStatus.FORBIDDEN,"Solicitante não pode aprovar ou rejeitar a própria solicitação.");if(!request.status().equals("PENDING")||request.version()!=input.version())throw error(HttpStatus.CONFLICT,"Solicitação já decidida ou alterada.");
  if(input.approve()){var requester=new Actor(a.tenantId(),request.requestedBy(),"","");access.requireBranch(requester,request.branchId());var quote=pricing.quote(requester,request.branchId(),request.items().stream().map(CartPricing.Line::input).toList());String original=db.queryForObject("SELECT cart_hash FROM pos_discount_request WHERE tenant_id=? AND id=?",String.class,a.tenantId(),id);if(!quote.hash().equals(original))throw error(HttpStatus.CONFLICT,"Produtos mudaram. Solicite nova aprovação.");}
  var now=OffsetDateTime.now(ZoneOffset.UTC);db.update("UPDATE pos_discount_request SET status=?,version=version+1,policy_version=?,decision_request_id=?,decision_fingerprint=?,decision_note=?,decided_by=?,decided_at=?,expires_at=? WHERE tenant_id=? AND id=?",input.approve()?"APPROVED":"REJECTED",policy(a,request.branchId()).version(),input.requestId(),hash,note,a.userId(),now,input.approve()?now.plusMinutes(30):null,a.tenantId(),id);audit.record(a,input.approve()?"POS_DISCOUNT_APPROVED":"POS_DISCOUNT_REJECTED",id);return get(a,id);
 }
 public void authorize(Actor a,UUID branch,CartPricing.Quote quote,UUID approval){var policy=policy(a,branch);boolean above=quote.items().stream().anyMatch(i->i.discountAmount().multiply(new BigDecimal("100")).compareTo(i.grossTotal().multiply(policy.operatorPercent()))>0);if(quote.discountTotal().signum()==0){if(approval!=null)throw error(HttpStatus.BAD_REQUEST,"Aprovação informada sem desconto.");return;}pricing.require(a,"pos:discount");if(approval==null){if(above)throw error(HttpStatus.FORBIDDEN,"Desconto excede o limite por item. Solicite aprovação de outro gestor.");return;}
  var request=get(a,approval);String hash=db.queryForObject("SELECT cart_hash FROM pos_discount_request WHERE tenant_id=? AND id=?",String.class,a.tenantId(),approval);
  if(!request.requestedBy().equals(a.userId())||!request.branchId().equals(branch)||!request.status().equals("APPROVED")||!hash.equals(quote.hash())||request.policyVersion()!=policy.version()||request.expiresAt().isBefore(OffsetDateTime.now(ZoneOffset.UTC)))throw error(HttpStatus.CONFLICT,"Aprovação não corresponde ao carrinho, expirou, foi usada ou a política mudou.");
  Long valid=db.queryForObject("SELECT COUNT(*) FROM app_user u JOIN user_permission p ON p.tenant_id=u.tenant_id AND p.user_id=u.id WHERE u.tenant_id=? AND u.id=? AND u.active=TRUE AND p.permission='pos:discount-approve' AND (u.all_branches=TRUE OR EXISTS(SELECT 1 FROM user_branch_access b WHERE b.tenant_id=u.tenant_id AND b.user_id=u.id AND b.branch_id=?))",Long.class,a.tenantId(),request.decidedBy(),branch);if(valid!=1)throw error(HttpStatus.CONFLICT,"O aprovador perdeu a autorização para esta filial.");
 }
 public void consume(Actor a,UUID approval,UUID sale){if(approval!=null){db.update("UPDATE pos_discount_request SET status='CONSUMED',version=version+1,sale_id=? WHERE tenant_id=? AND id=?",sale,a.tenantId(),approval);audit.record(a,"POS_DISCOUNT_CONSUMED",approval);}}
}
